var findClosestNumber = function(nums) {
    let best = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const x = nums[i];
        if (Math.abs(x) < Math.abs(best) || (Math.abs(x) === Math.abs(best) && x > best)) {
            best = x;
        }
    }
    return best;
};
